const raw = $input.first().json || {};

// n8n webhook v2: el payload de Slack llega en raw.body
let body = raw.body && typeof raw.body === 'object' ? raw.body : raw;

// Slack Interactivity (block_actions, view_submission, etc.) llega como
// application/x-www-form-urlencoded con un campo "payload" stringified.
if (body.payload && typeof body.payload === 'string') {
  try {
    body = JSON.parse(body.payload);
  } catch (e) {
    console.log('payload parse error:', e.message);
  }
}

console.log('--- Parsear evento DEBUG ---');
console.log('outer_type:', body.type);
console.log('event_type:', body.event?.type);
console.log('channel_type:', body.event?.channel_type);

// 1. Slack URL verification challenge
if (body.type === 'url_verification') {
  return [{ json: { is_valid: false, event_type: 'url_verification', challenge: body.challenge } }];
}

// 2. Botones de feedback (block_actions): 👍 o 👎
if (body.type === 'block_actions') {
  const action = (body.actions || [])[0] || {};
  const action_id = action.action_id || '';
  const value = action.value || '';
  const parts = value.split('_');
  const memory_id = parseInt(parts[parts.length - 1]) || null;
  const trigger_id = body.trigger_id || '';
  const user_id = (body.user || {}).id || '';
  const response_url = body.response_url || '';

  if (action_id === 'feedback_good') {
    return [{ json: {
      is_valid: false,
      event_type: 'feedback_good',
      memory_id, user_id, response_url,
      label: '¡Gracias! El Oráculo tomará nota 📜✨'
    }}];
  }
  if (action_id === 'feedback_bad') {
    return [{ json: {
      is_valid: false,
      event_type: 'feedback_bad',
      memory_id, user_id, trigger_id
    }}];
  }
  return [{ json: { is_valid: false, event_type: 'unknown_action', debug: action_id } }];
}

// 3. Submit del modal de 👎
if (body.type === 'view_submission') {
  const view = body.view || {};
  const memory_id = parseInt(view.private_metadata) || null;
  const note = view.state?.values?.feedback_block?.feedback_text?.value || '';
  const user_id = (body.user || {}).id || '';
  return [{ json: {
    is_valid: false,
    event_type: 'view_submission_feedback',
    memory_id, note, user_id
  }}];
}

// 4. Solo procesamos event_callback de aquí en adelante
if (body.type !== 'event_callback') {
  return [{ json: { is_valid: false, event_type: body.type || 'unknown', debug: JSON.stringify(body).slice(0, 300) } }];
}

const event = body.event || {};

// 5. Ignorar mensajes del propio bot (evita loops)
if (event.bot_id || event.subtype === 'bot_message' || event.subtype === 'message_changed') {
  return [{ json: { is_valid: false, event_type: 'bot_skip' } }];
}

const event_type_raw = event.type || '';
if (!['app_mention', 'message'].includes(event_type_raw)) {
  return [{ json: { is_valid: false, event_type: event_type_raw || 'unknown' } }];
}

// 6. Filtro de seguridad: en canales solo respondemos a app_mention.
// Para 'message' exigimos que sea DM (channel_type === 'im').
// Esto evita que el bot conteste a TODOS los mensajes si por error se suscribe message.channels.
if (event_type_raw === 'message' && event.channel_type !== 'im') {
  return [{ json: { is_valid: false, event_type: 'channel_message_no_mention', debug: event.channel_type } }];
}

// 7. Extraer campos
const channel_id = event.channel || '';
const user_id = event.user || '';
const thread_ts = event.thread_ts || null;
const msg_ts = event.ts || null;

// 8. Limpiar texto: quitar @menciones (<@U123ABC>)
let text = (event.text || '').trim();
text = text.replace(/<@[A-Z0-9]+>/gi, '').trim();

if (!text) {
  return [{ json: { is_valid: false, event_type: 'empty_text' } }];
}

return [{ json: {
  is_valid: true,
  event_type: 'agent_question',
  source_type: event_type_raw,
  text,
  channel_id,
  thread_ts,
  msg_ts,
  user_id
}}];
